"""Fifth curated tranche of materially distinct Python algorithms."""

ADVANCED_TASK_CODE_SPECS_5 = (
    ("fenwick_queries", "Write a Python function that processes point-add and inclusive-prefix-sum operations over an initial numeric sequence using a Fenwick tree.", "def process_fenwick_operations(values, operations):\n    tree = [0] * (len(values) + 1)\n    def add(index, amount):\n        index += 1\n        while index < len(tree):\n            tree[index] += amount\n            index += index & -index\n    def prefix(index):\n        total = 0\n        index += 1\n        while index > 0:\n            total += tree[index]\n            index -= index & -index\n        return total\n    for index, value in enumerate(values):\n        add(index, value)\n    answers = []\n    for operation in operations:\n        if operation[0] == \"add\":\n            add(operation[1], operation[2])\n        elif operation[0] == \"prefix\":\n            answers.append(prefix(operation[1]))\n        else:\n            raise ValueError(\"unknown operation\")\n    return answers"),
    ("difference_range_updates", "Write a Python function that applies inclusive range-add updates to a fixed-length zero sequence using a difference array and returns the final values.", "def apply_range_additions(length, updates):\n    if length < 0:\n        raise ValueError(\"length must be nonnegative\")\n    difference = [0] * (length + 1)\n    for start, end, amount in updates:\n        if not 0 <= start <= end < length:\n            raise ValueError(\"invalid range\")\n        difference[start] += amount\n        difference[end + 1] -= amount\n    result = []\n    current = 0\n    for index in range(length):\n        current += difference[index]\n        result.append(current)\n    return result"),
    ("two_dimensional_prefix_queries", "Write a Python function that answers inclusive rectangular sum queries over a rectangular numeric matrix using a two-dimensional prefix table.", "def rectangle_sum_queries(matrix, queries):\n    if not matrix:\n        return [0 for _ in queries]\n    rows, columns = len(matrix), len(matrix[0])\n    if any(len(row) != columns for row in matrix):\n        raise ValueError(\"matrix must be rectangular\")\n    prefix = [[0] * (columns + 1) for _ in range(rows + 1)]\n    for row in range(rows):\n        running = 0\n        for column in range(columns):\n            running += matrix[row][column]\n            prefix[row + 1][column + 1] = prefix[row][column + 1] + running\n    result = []\n    for top, left, bottom, right in queries:\n        if not (0 <= top <= bottom < rows and 0 <= left <= right < columns):\n            raise ValueError(\"invalid rectangle\")\n        result.append(prefix[bottom + 1][right + 1] - prefix[top][right + 1] - prefix[bottom + 1][left] + prefix[top][left])\n    return result"),
    ("sparse_table_minimum", "Write a Python function that answers inclusive static range-minimum queries by building a sparse table without mutating the numeric sequence.", "def static_range_minimums(values, queries):\n    if not values:\n        raise ValueError(\"values must be non-empty\")\n    table = [list(values)]\n    width = 2\n    while width <= len(values):\n        half = width // 2\n        previous = table[-1]\n        table.append([min(previous[index], previous[index + half]) for index in range(len(values) - width + 1)])\n        width *= 2\n    answers = []\n    for left, right in queries:\n        if not 0 <= left <= right < len(values):\n            raise ValueError(\"invalid range\")\n        power = (right - left + 1).bit_length() - 1\n        span = 1 << power\n        answers.append(min(table[power][left], table[power][right - span + 1]))\n    return answers"),
    ("iterative_segment_tree", "Write a Python function that processes point replacements and half-open range-sum queries using an iterative segment tree over a copied numeric sequence.", "def process_segment_tree(values, operations):\n    size = len(values)\n    tree = [0] * size + list(values)\n    for index in range(size - 1, 0, -1):\n        tree[index] = tree[index * 2] + tree[index * 2 + 1]\n    answers = []\n    for operation in operations:\n        if operation[0] == \"set\":\n            position = operation[1] + size\n            tree[position] = operation[2]\n            while position > 1:\n                position //= 2\n                tree[position] = tree[position * 2] + tree[position * 2 + 1]\n        elif operation[0] == \"sum\":\n            left, right = operation[1] + size, operation[2] + size\n            total = 0\n            while left < right:\n                if left % 2:\n                    total += tree[left]\n                    left += 1\n                if right % 2:\n                    right -= 1\n                    total += tree[right]\n                left //= 2\n                right //= 2\n            answers.append(total)\n        else:\n            raise ValueError(\"unknown operation\")\n    return answers"),
    ("binary_heap_schedule", "Write a Python function that processes enqueue and dequeue operations for a minimum-priority queue, resolving equal priorities by insertion order and returning dequeued payloads.", "def process_priority_queue(operations):\n    heap = []\n    order = 0\n    result = []\n    def push(item):\n        heap.append(item)\n        index = len(heap) - 1\n        while index:\n            parent = (index - 1) // 2\n            if heap[parent] <= heap[index]:\n                break\n            heap[parent], heap[index] = heap[index], heap[parent]\n            index = parent\n    for operation in operations:\n        if operation[0] == \"enqueue\":\n            push((operation[1], order, operation[2]))\n            order += 1\n        elif operation[0] == \"dequeue\":\n            if not heap:\n                raise ValueError(\"empty queue\")\n            heap[0], heap[-1] = heap[-1], heap[0]\n            result.append(heap.pop()[2])\n            index = 0\n            while index * 2 + 1 < len(heap):\n                child = index * 2 + 1\n                if child + 1 < len(heap) and heap[child + 1] < heap[child]:\n                    child += 1\n                if heap[index] <= heap[child]:\n                    break\n                heap[index], heap[child] = heap[child], heap[index]\n                index = child\n        else:\n            raise ValueError(\"unknown operation\")\n    return result"),
    ("lru_access_simulation", "Write a Python function that simulates a positive-capacity least-recently-used cache for key accesses and returns the keys from least to most recently used at the end.", "def simulate_lru_cache(accesses, capacity):\n    if capacity <= 0:\n        raise ValueError(\"capacity must be positive\")\n    order = []\n    present = set()\n    for key in accesses:\n        if key in present:\n            order.remove(key)\n        else:\n            present.add(key)\n            if len(order) == capacity:\n                present.remove(order.pop(0))\n        order.append(key)\n    return order"),
    ("trie_prefix_counts", "Write a Python function that returns how many supplied words begin with each query prefix by constructing a character trie with subtree counts.", "def prefix_word_counts(words, prefixes):\n    root = {}\n    for word in words:\n        node = root\n        node[None] = node.get(None, 0) + 1\n        for character in word:\n            node = node.setdefault(character, {})\n            node[None] = node.get(None, 0) + 1\n    result = []\n    for prefix in prefixes:\n        node = root\n        for character in prefix:\n            if character not in node:\n                node = None\n                break\n            node = node[character]\n        result.append(0 if node is None else node.get(None, 0))\n    return result"),
    ("suffix_array", "Write a Python function that returns the starting indices of all suffixes of a string in lexicographic order using iterative rank doubling.", "def suffix_array(text):\n    size = len(text)\n    order = list(range(size))\n    ranks = [ord(character) for character in text]\n    width = 1\n    while width < size:\n        order.sort(key=lambda index: (ranks[index], ranks[index + width] if index + width < size else -1))\n        updated = [0] * size\n        for position in range(1, size):\n            previous, current = order[position - 1], order[position]\n            previous_key = (ranks[previous], ranks[previous + width] if previous + width < size else -1)\n            current_key = (ranks[current], ranks[current + width] if current + width < size else -1)\n            updated[current] = updated[previous] + (current_key != previous_key)\n        ranks = updated\n        width *= 2\n    return order"),
    ("z_pattern_matches", "Write a Python function that returns every starting index of a non-empty pattern in text by computing Z-values over a combined sequence.", "def z_match_indices(text, pattern):\n    if not pattern:\n        raise ValueError(\"pattern must be non-empty\")\n    combined = list(pattern) + [None] + list(text)\n    z = [0] * len(combined)\n    left = right = 0\n    for index in range(1, len(combined)):\n        if index <= right:\n            z[index] = min(right - index + 1, z[index - left])\n        while index + z[index] < len(combined) and combined[z[index]] == combined[index + z[index]]:\n            z[index] += 1\n        if index + z[index] - 1 > right:\n            left, right = index, index + z[index] - 1\n    offset = len(pattern) + 1\n    return [index - offset for index in range(offset, len(combined)) if z[index] == len(pattern)]"),
    ("rolling_hash_matches", "Write a Python function that returns every occurrence of a non-empty lowercase pattern in lowercase text using a rolling polynomial hash and direct collision verification.", "def rolling_hash_match_indices(text, pattern):\n    if not pattern:\n        raise ValueError(\"pattern must be non-empty\")\n    if len(pattern) > len(text):\n        return []\n    base, modulus = 257, 1000000007\n    power = pow(base, len(pattern) - 1, modulus)\n    target_hash = window_hash = 0\n    for pattern_character, text_character in zip(pattern, text):\n        target_hash = (target_hash * base + ord(pattern_character)) % modulus\n        window_hash = (window_hash * base + ord(text_character)) % modulus\n    result = []\n    for start in range(len(text) - len(pattern) + 1):\n        if window_hash == target_hash and text[start:start + len(pattern)] == pattern:\n            result.append(start)\n        if start + len(pattern) < len(text):\n            window_hash = (window_hash - ord(text[start]) * power) % modulus\n            window_hash = (window_hash * base + ord(text[start + len(pattern)])) % modulus\n    return result"),
    ("minimum_string_rotation", "Write a Python function that returns the lexicographically smallest rotation of a non-empty string using a two-candidate linear scan.", "def minimum_string_rotation(text):\n    if not text:\n        raise ValueError(\"text must be non-empty\")\n    doubled = text + text\n    first, second, offset = 0, 1, 0\n    while first < len(text) and second < len(text) and offset < len(text):\n        if doubled[first + offset] == doubled[second + offset]:\n            offset += 1\n            continue\n        if doubled[first + offset] > doubled[second + offset]:\n            first = first + offset + 1\n            if first == second:\n                first += 1\n        else:\n            second = second + offset + 1\n            if first == second:\n                second += 1\n        offset = 0\n    start = min(first, second)\n    return doubled[start:start + len(text)]"),
    ("word_ladder_length", "Write a Python function that returns the number of words in the shortest one-letter-change path between equal-length start and goal words using a supplied dictionary, or zero when impossible.", "def word_ladder_length(start, goal, words):\n    if len(start) != len(goal):\n        return 0\n    remaining = {word for word in words if len(word) == len(start)}\n    if goal not in remaining:\n        return 0\n    queue = [(start, 1)]\n    remaining.discard(start)\n    position = 0\n    while position < len(queue):\n        word, distance = queue[position]\n        position += 1\n        if word == goal:\n            return distance\n        neighbors = [candidate for candidate in remaining if sum(left != right for left, right in zip(word, candidate)) == 1]\n        for neighbor in neighbors:\n            remaining.remove(neighbor)\n            queue.append((neighbor, distance + 1))\n    return 0"),
    ("eulerian_trail", "Write a Python function that returns an Eulerian trail through directed edges as a node list using every edge exactly once, or raises ValueError when the supplied start cannot cover all edges.", "def directed_eulerian_trail(edges, start):\n    adjacency = {}\n    for source, target in edges:\n        adjacency.setdefault(source, []).append(target)\n    for targets in adjacency.values():\n        targets.reverse()\n    stack = [start]\n    trail = []\n    while stack:\n        node = stack[-1]\n        if adjacency.get(node):\n            stack.append(adjacency[node].pop())\n        else:\n            trail.append(stack.pop())\n    trail.reverse()\n    if len(trail) != len(edges) + 1:\n        raise ValueError(\"edges do not form a trail from start\")\n    return trail"),
    ("undirected_bridges", "Write a Python function that returns every bridge edge in an undirected adjacency dictionary using discovery and low-link times.", "def undirected_bridge_edges(graph):\n    discovery = {}\n    low = {}\n    bridges = []\n    time = 0\n    def visit(node, parent):\n        nonlocal time\n        discovery[node] = low[node] = time\n        time += 1\n        for neighbor in graph.get(node, []):\n            if neighbor == parent:\n                continue\n            if neighbor not in discovery:\n                visit(neighbor, node)\n                low[node] = min(low[node], low[neighbor])\n                if low[neighbor] > discovery[node]:\n                    bridges.append((node, neighbor))\n            else:\n                low[node] = min(low[node], discovery[neighbor])\n    nodes = set(graph)\n    for neighbors in graph.values():\n        nodes.update(neighbors)\n    for node in nodes:\n        if node not in discovery:\n            visit(node, None)\n    return bridges"),
    ("articulation_points", "Write a Python function that returns articulation points of an undirected adjacency dictionary using depth-first discovery and low-link values.", "def articulation_points(graph):\n    discovery = {}\n    low = {}\n    result = set()\n    time = 0\n    def visit(node, parent):\n        nonlocal time\n        discovery[node] = low[node] = time\n        time += 1\n        children = 0\n        for neighbor in graph.get(node, []):\n            if neighbor == parent:\n                continue\n            if neighbor not in discovery:\n                children += 1\n                visit(neighbor, node)\n                low[node] = min(low[node], low[neighbor])\n                if parent is not None and low[neighbor] >= discovery[node]:\n                    result.add(node)\n            else:\n                low[node] = min(low[node], discovery[neighbor])\n        if parent is None and children > 1:\n            result.add(node)\n    nodes = set(graph)\n    for neighbors in graph.values():\n        nodes.update(neighbors)\n    for node in nodes:\n        if node not in discovery:\n            visit(node, None)\n    return result"),
    ("a_star_grid", "Write a Python function that returns a shortest four-directional path between open cells in a rectangular zero-one grid using Manhattan-distance A-star search, or an empty list when unreachable.", "def a_star_grid_path(grid, start, goal):\n    frontier = [(0, 0, start)]\n    parent = {start: None}\n    cost = {start: 0}\n    while frontier:\n        frontier.sort(reverse=True)\n        _, distance, cell = frontier.pop()\n        if distance != cost[cell]:\n            continue\n        if cell == goal:\n            path = []\n            while cell is not None:\n                path.append(cell)\n                cell = parent[cell]\n            return list(reversed(path))\n        row, column = cell\n        for neighbor in ((row - 1, column), (row + 1, column), (row, column - 1), (row, column + 1)):\n            next_row, next_column = neighbor\n            if 0 <= next_row < len(grid) and 0 <= next_column < len(grid[0]) and grid[next_row][next_column] == 0:\n                candidate = distance + 1\n                if candidate < cost.get(neighbor, float(\"inf\")):\n                    cost[neighbor] = candidate\n                    parent[neighbor] = cell\n                    priority = candidate + abs(next_row - goal[0]) + abs(next_column - goal[1])\n                    frontier.append((priority, candidate, neighbor))\n    return []"),
    ("alien_alphabet", "Write a Python function that derives one valid character order from lexicographically sorted words in an unknown alphabet, raising ValueError for contradictory prefixes or cycles.", "def derive_alien_alphabet(words):\n    graph = {character: set() for word in words for character in word}\n    indegree = {character: 0 for character in graph}\n    for first, second in zip(words, words[1:]):\n        if len(first) > len(second) and first.startswith(second):\n            raise ValueError(\"contradictory prefix order\")\n        for left, right in zip(first, second):\n            if left != right:\n                if right not in graph[left]:\n                    graph[left].add(right)\n                    indegree[right] += 1\n                break\n    ready = sorted(character for character, degree in indegree.items() if degree == 0)\n    result = []\n    while ready:\n        character = ready.pop(0)\n        result.append(character)\n        for neighbor in sorted(graph[character]):\n            indegree[neighbor] -= 1\n            if indegree[neighbor] == 0:\n                ready.append(neighbor)\n                ready.sort()\n    if len(result) != len(indegree):\n        raise ValueError(\"alphabet constraints contain a cycle\")\n    return \"\".join(result)"),
    ("dependency_semesters", "Write a Python function that groups tasks into the minimum prerequisite-respecting semester layers from a task-to-prerequisites dictionary, raising ValueError for cycles.", "def prerequisite_semesters(prerequisites):\n    tasks = set(prerequisites)\n    for required in prerequisites.values():\n        tasks.update(required)\n    remaining = {task: set(prerequisites.get(task, [])) for task in tasks}\n    semesters = []\n    completed = set()\n    while len(completed) < len(tasks):\n        ready = sorted(task for task in tasks - completed if remaining[task] <= completed)\n        if not ready:\n            raise ValueError(\"prerequisites contain a cycle\")\n        semesters.append(ready)\n        completed.update(ready)\n    return semesters"),
    ("huffman_codes", "Write a Python function that returns binary prefix codes for symbols with positive frequencies by repeatedly combining the two lightest trees, resolving ties by input order.", "def huffman_codes(frequencies):\n    if not frequencies:\n        return {}\n    queue = []\n    order = 0\n    for symbol, frequency in frequencies.items():\n        if frequency <= 0:\n            raise ValueError(\"frequencies must be positive\")\n        queue.append((frequency, order, symbol))\n        order += 1\n    while len(queue) > 1:\n        queue.sort(reverse=True)\n        first = queue.pop()\n        second = queue.pop()\n        queue.append((first[0] + second[0], order, (first[2], second[2])))\n        order += 1\n    codes = {}\n    stack = [(queue[0][2], \"\")]\n    while stack:\n        node, prefix = stack.pop()\n        if isinstance(node, tuple):\n            stack.append((node[1], prefix + \"1\"))\n            stack.append((node[0], prefix + \"0\"))\n        else:\n            codes[node] = prefix or \"0\"\n    return codes"),
    ("gaussian_elimination", "Write a Python function that solves a nonsingular square linear system using Gaussian elimination with partial pivoting on copied coefficient rows and values.", "def solve_linear_system(coefficients, values):\n    size = len(coefficients)\n    if len(values) != size or any(len(row) != size for row in coefficients):\n        raise ValueError(\"system must be square\")\n    matrix = [list(row) + [values[index]] for index, row in enumerate(coefficients)]\n    for column in range(size):\n        pivot = max(range(column, size), key=lambda row: abs(matrix[row][column]))\n        if matrix[pivot][column] == 0:\n            raise ValueError(\"singular system\")\n        matrix[column], matrix[pivot] = matrix[pivot], matrix[column]\n        divisor = matrix[column][column]\n        matrix[column] = [value / divisor for value in matrix[column]]\n        for row in range(size):\n            if row == column:\n                continue\n            factor = matrix[row][column]\n            matrix[row] = [left - factor * right for left, right in zip(matrix[row], matrix[column])]\n    return [matrix[row][-1] for row in range(size)]"),
    ("matrix_determinant", "Write a Python function that computes the determinant of a square numeric matrix by elimination with row swaps without mutating the matrix.", "def matrix_determinant(matrix):\n    size = len(matrix)\n    if any(len(row) != size for row in matrix):\n        raise ValueError(\"matrix must be square\")\n    work = [list(row) for row in matrix]\n    determinant = 1\n    for column in range(size):\n        pivot = max(range(column, size), key=lambda row: abs(work[row][column]))\n        if work[pivot][column] == 0:\n            return 0\n        if pivot != column:\n            work[column], work[pivot] = work[pivot], work[column]\n            determinant = -determinant\n        pivot_value = work[column][column]\n        determinant *= pivot_value\n        for row in range(column + 1, size):\n            factor = work[row][column] / pivot_value\n            for inner in range(column + 1, size):\n                work[row][inner] -= factor * work[column][inner]\n    return determinant"),
    ("discrete_convolution", "Write a Python function that returns the full discrete convolution of two numeric sequences using direct multiplication and returns an empty list when either input is empty.", "def discrete_convolution(first, second):\n    if not first or not second:\n        return []\n    result = [0] * (len(first) + len(second) - 1)\n    for left_index, left_value in enumerate(first):\n        for right_index, right_value in enumerate(second):\n            result[left_index + right_index] += left_value * right_value\n    return result"),
    ("convex_hull", "Write a Python function that returns the vertices of the convex hull of distinct two-dimensional points in counterclockwise order using the monotone-chain algorithm.", "def convex_hull(points):\n    ordered = sorted(set(points))\n    if len(ordered) <= 1:\n        return ordered\n    def cross(origin, first, second):\n        return (first[0] - origin[0]) * (second[1] - origin[1]) - (first[1] - origin[1]) * (second[0] - origin[0])\n    lower = []\n    for point in ordered:\n        while len(lower) >= 2 and cross(lower[-2], lower[-1], point) <= 0:\n            lower.pop()\n        lower.append(point)\n    upper = []\n    for point in reversed(ordered):\n        while len(upper) >= 2 and cross(upper[-2], upper[-1], point) <= 0:\n            upper.pop()\n        upper.append(point)\n    return lower[:-1] + upper[:-1]"),
)
